% TEST_RUN_SESSION_DRY  Dry run of run_session without an arena (26 Oct 2026, automatic design).
%
% Uses the read-out tables of JY1008 and the stage-1 files of TUTL_20251023a (ephys-standard-analysis/
% tools/out, copied first because that folder is regenerated by other sessions), the pre-made LHS
% Protocol 1 package of this repository, and a synthesized Protocol 2 package (currentExp with the
% create_protocol2 ordering and a gray 89-frame bar-flash pattern). Writes everything under a scratch
% folder. Checks: both Protocol 2 modes, the stage-2 package, the automatic decisions and their
% fallbacks (no usable PD, center sanity check, override), failure injection with resume, abandon,
% the duration contract. Run with nested_RF_stimulus/src on the path and, on a Mac, maDisplayTools.

here = fileparts(mfilename('fullpath'));
repo = fileparts(fileparts(here));
addpath(genpath(fullfile(repo, 'src')));
analysis_repo = fullfile(fileparts(repo), 'ephys-standard-analysis');
tools_out = fullfile(analysis_repo, 'tools', 'out');
p1_package = fullfile(repo, 'protocols', 'LHS', 'protocol1_10kHz_4reps_12px_6px_LHS_2sbkg_200msfl_50msint_12-13-24_14-33-03');
assert(isfile(fullfile(tools_out, 'JY1008_prot3b_blocks.csv')), 'read-out tables of JY1008 not found in %s', tools_out);
assert(isfile(fullfile(tools_out, 'TUTL_20251023a_stage2_sequence.csv')), 'stage files of TUTL_20251023a not found in %s', tools_out);
assert(isfolder(fullfile(p1_package, 'Patterns')), 'Protocol 1 package not found: %s', p1_package);

scratch = fullfile(tempdir, ['run_session_dry_' char(datetime('now', 'Format', 'yyyyMMdd_HHmmss'))]);
mkdir(scratch);
fprintf('Scratch folder: %s\n', scratch);
global NFAIL; NFAIL = 0;

% stable copy of the read-out tables; the TUTL stage-1 files renamed to the JY1008 tag
readout_dir = fullfile(scratch, 'readout_src'); mkdir(readout_dir);
for f = dir(fullfile(tools_out, 'JY1008_*')).', copyfile(fullfile(f.folder, f.name), fullfile(readout_dir, f.name)); end
for nm = {'stage1.json', 'stage2_sequence.csv', 'stage2_bars.csv'}
    copyfile(fullfile(tools_out, ['TUTL_20251023a_' nm{1}]), fullfile(readout_dir, ['JY1008_' nm{1}]));
end
% the Protocol 1 peak used as the override: the 6-px square at columns 59..64, rows 25..30 (frame 190 of
% the LHS pattern), 2.8 px from JY1008's read-out center [62.91 29.89]
peak_frame = 190;
P1 = load(fullfile(p1_package, 'Patterns', dir(fullfile(p1_package, 'Patterns', '0002_*.mat')).name));
fpk = P1.pattern.Pats(:, :, peak_frame); [rr, cc] = find(fpk ~= mode(fpk(:)));    % the LHS pattern's background is 6
p1xy = [median(cc), median(rr)];
L = jsondecode(fileread(fullfile(readout_dir, 'JY1008_locations.json')));
center = L.rf_center_col_row_1based(:).';
fprintf('Protocol 1 peak frame %d at col/row %s; read-out center %s; distance %.2f px\n', peak_frame, mat2str(p1xy), mat2str(center), norm(p1xy - center));

% a synthesized Protocol 2 package in create_protocol2's shape: patterns 1 gray, 2-3 bars, 4 bar-flash
% slow (89 frames), 5 bar-flash fast; pattern_order with the two bar-flash conditions last
p2pkg = fullfile(scratch, 'p2_synth'); mkdir(fullfile(p2pkg, 'Patterns')); mkdir(fullfile(p2pkg, 'Functions'));
names = {'0001_gray_G4', '0002_bars_a_G4', '0003_bars_b_G4', '0004_bar_flashes_slow_CROP30_FLASHES_G4', '0005_bar_flashes_fast_CROP30_FLASHES_G4'};
nfr = [1 68 68 89 89];
for k = 1:5
    pattern = struct('Pats', 4*ones(48, 192, nfr(k)), 'x_num', nfr(k), 'y_num', 1, 'gs_val', 4, 'param', struct('ID', k)); %#ok<NASGU>
    save(fullfile(p2pkg, 'Patterns', [names{k} '.mat']), 'pattern');
end
currentExp = struct(); currentExp.pattern.pattNames = cellfun(@(n) [n '.mat'], names, 'UniformOutput', false); currentExp.totalDuration = 0;
pattern_order = [1 2 2 3 3 1 4 1 5]; func_order = [6 1 2 1 2 7 3 7 4]; trial_dur = [10 3.3 3.3 2.1 2.1 3 22 3 11]; %#ok<NASGU>
save(fullfile(p2pkg, 'currentExp.mat'), 'currentExp', 'pattern_order', 'func_order', 'trial_dur');
p2pkg_C = fullfile(scratch, 'p2_synth_C'); copyfile(p2pkg, p2pkg_C);

%% 1. Full mode (Protocol 2 as today, one read-out), peak frame given as the override
exp1 = fullfile(scratch, 'cell_A_full');
S = run_session(exp1, 'dry_run', true, 'cell', 'JY1008', 'side', 'L', 'p2_mode', 'full', 'p1_package', p1_package, ...
    'peak_frame', peak_frame, 'readout_dir', readout_dir, 'analysis_repo', analysis_repo);
st = containers.Map({S.steps.id}, {S.steps.status});
check(isequal({S.steps.id}, {'dark30', 'p1', 'p1_peak', 'reaim', 'p1_confirm', 'p2', 'readout', 'build', 'p3b', 'p4'}) && strcmp(st('p1_confirm'), 'skipped') && ...
    all(strcmp(values(st, setdiff(keys(st), {'p1_confirm'})), 'done')), 'full mode: 10 steps, all done (peak at row 27.5: no re-aim, p1_confirm skipped)');
check(isfile(fullfile(exp1, 'session_state.json')) && isfile(fullfile(exp1, 'session_log.txt')) && isfile(fullfile(exp1, 'decisions.json')), 'state, log and decision files written');
D = S.decisions; dn = {D.decision};
check(any(strcmp(dn, 'aim')) && contains(D(strcmp(dn, 'aim')).outcome, 'override') && isequal(S.out.p1_peak.xy, p1xy), 'decision aim: peak frame override logged with its col/row');
dc = D(strcmp(dn, 'center'));
check(isscalar(dc) && ~dc.fallback && isequal(S.center_shift_px, [0 0]) && S.out.readout.checks.near_p1 && abs(S.out.readout.checks.dist_to_p1_px - norm(p1xy - center)) < 1e-9, ...
    sprintf('decision center: read-out center accepted (%.2f px from the Protocol 1 peak, no shift)', S.out.readout.checks.dist_to_p1_px));
check(islogical(S.out.readout.checks.inside_bar_set) && S.out.readout.checks.inside_bar_set && S.out.readout.checks.peak_above_floor, 'center checks: inside the bar set and center peak above the floor');
p1s = jsondecode(fileread(fullfile(exp1, 'p1', 'Reports', 'run_status.json')));
check(p1s.rows_total == 9 && strcmp(p1s.state, 'completed') && abs(sum([p1s.rows.duration_s]) - 322.8) < 1e-6, 'Protocol 1: 9 rows, 322.8 s, completed');
p3 = S.out.build.p3b; p4 = S.out.build.p4;
check(p3.n_frames == 26 && p3.n_blocks == 26 && abs(p3.programmed_s - 454) < 1e-6 && p3.n_events == 548, 'Prot3b: 26 frames, 26 blocks, 454 s, 548 flashes');
B = readtable(fullfile(exp1, 'p3b', 'Reports', 'block_ledger.csv'), 'Delimiter', ',');
check(isequal(B.requested_current_pA(1:5).', [0.5 -0.5 0 -0.5 0.5]) && isequal(B.requested_current_pA(21:26).', [-1 0 1 1 0 -1]), 'Prot3b block currents as the hand-over');
check(numel(dir(fullfile(exp1, 'p3b', 'Analog Output Functions', '*.afn'))) == 7, 'Prot3b: 7 AO functions');
m = load(fullfile(exp1, 'p3b', 'Analog Output Functions', dir(fullfile(exp1, 'p3b', 'Analog Output Functions', '0002_*')).name));
fid = fopen(fullfile(exp1, 'p3b', 'Analog Output Functions', 'ao0002.afn'), 'r'); hdr = fread(fid, 512, '*uint8'); dat = fread(fid, inf, '*int16'); fclose(fid);
code_expected = round((0.125 + 10)/20*65535 - 32768); zero_code = round((0 + 10)/20*65535 - 32768);
check(typecast(hdr(1:4).', 'uint32') == 2*numel(m.afnparam.func) && numel(dat) == 16200 && dat(1) == code_expected && dat(16100) == code_expected && dat(16101) == zero_code, ...
    sprintf('AFN +0.5 pA: 0.125 V (code %d) for 16.1 s then 0 V (code %d), header consistent', code_expected, zero_code));
Bt = readtable(fullfile(readout_dir, 'JY1008_prot3b_blocks.csv'), 'TextType', 'string', 'Delimiter', ',');
fr1 = sscanf(char(Bt.frames(1)), '%d').';
m = load(fullfile(exp1, 'p3b', 'Functions', dir(fullfile(exp1, 'p3b', 'Functions', '0002_*')).name)); f = m.pfnparam.func;
check(numel(f) == 8100 && all(f(1:1500) == 1) && f(1501) == fr1(1) && f(1580) == fr1(1) && f(1581) == 1 && f(1801) == fr1(2), 'PFN block 1: 3 s gray, then 160 ms frame + 440 ms gray in the table order');
P = load(fullfile(exp1, 'p3b', 'Patterns', dir(fullfile(exp1, 'p3b', 'Patterns', '0001_*')).name)); Pats = P.pattern.Pats;
Ft = readtable(fullfile(readout_dir, 'JY1008_prot3b_frames.csv'), 'TextType', 'string', 'Delimiter', ',');
c0 = Ft.col_start(Ft.frame == 2); r0 = Ft.row_start(Ft.frame == 2);
check(isequal(size(Pats), [48 192 26]) && all(Pats(r0:r0+3, c0:c0+3, 2) == 0, 'all') && sum(Pats(:, :, 2) ~= 4, 'all') == 16 && all(Pats(r0:r0+3, c0:c0+3, 13) == 15, 'all'), ...
    sprintf('Prot3b pattern: frame 2 OFF and frame 13 ON at (col %d, row %d)', c0, r0));
check(p3.pat_written && isfield(P.pattern, 'data'), 'Prot3b .pat written with the native encoder');
Q = readtable(fullfile(readout_dir, 'JY1008_prot4_sequence.csv'), 'Delimiter', ',');
check(p4.n_flashes == height(Q) && abs(p4.programmed_s - (3 + sum(Q.flash_ms + Q.gray_ms)/1000 + 4)) < 1e-6, sprintf('Protocol 4: %d flashes, %.1f min', p4.n_flashes, p4.programmed_s/60));
r4 = jsondecode(fileread(fullfile(exp1, 'p4', 'Reports', 'run_status.json')));
check(r4.rows_total == 3 && strcmp(r4.state, 'completed') && isequal({r4.cleanup.step}, {'stopDisplay', 'setControlMode(1)', 'setPatternID(gray)', 'setPatternFunctionID(gray)', 'setPositionX(1)', 'setAOFunctionID(zero)', 'startDisplay(5) flush', 'setActiveAOChannels([]) (AO off)', 'stopLog', 'close'}), ...
    'Protocol 4 run: 3 rows, full cleanup sequence');

%% 2. Two-stage mode with the synthesized stage-1 package, 5 stage-2 repeats
exp2 = fullfile(scratch, 'cell_B_two_stage');
S2 = run_session(exp2, 'dry_run', true, 'cell', 'JY1008', 'side', 'L', 'p1_package', p1_package, 'peak_frame', peak_frame, ...
    'p2_folder', p2pkg, 'readout_dir', readout_dir, 'n_reps_stage2', 5, 'analysis_repo', analysis_repo);
st2 = containers.Map({S2.steps.id}, {S2.steps.status});
check(isequal({S2.steps.id}, {'dark30', 'p1', 'p1_peak', 'reaim', 'p1_confirm', 'p2a', 'readout1', 'p2b', 'readout', 'build', 'p3b', 'p4'}) && strcmp(st2('p1_confirm'), 'skipped') && ...
    all(strcmp(values(st2, setdiff(keys(st2), {'p1_confirm'})), 'done')), 'two-stage mode: 12 steps, all done (no re-aim, p1_confirm skipped)');
sa = jsondecode(fileread(fullfile(p2pkg, 'Reports', 'run_status.json')));
check(sa.rows_total == 21 && all(~ismember([sa.rows.pattern_id], [4 5])) && abs(sum([sa.rows.duration_s]) - 3*(10 + 3.3*2 + 2.1*2 + 3 + 3)) < 1e-6, 'stage 1: 7 non-bar-flash conditions x 3 reps = 21 rows, 80.4 s, no bar-flash pattern');
d2 = S2.decisions; dn2 = {d2.decision};
pdd = d2(strcmp(dn2, 'placement_pd')); pdd = pdd(1);
check(contains(pdd.outcome, 'placement PD 299.26') && contains(pdd.flags, '> 5 deg') && ~pdd.fallback, 'read-out 1: placement PD displayed with the > 5 deg flag (rule mean)');
ud = d2(strcmp(dn2, 'usable_pd'));
check(isscalar(ud) && ~ud.fallback && strcmp(S2.out.readout1.stage2_mode, 'bars22'), 'read-out 1: usable PD (L28 0.195 >= 0.1), stage 2 = 22 bars');
sb = jsondecode(fileread(fullfile(exp2, 'p2b', 'Reports', 'run_status.json')));
check(sb.rows_total == 12 && S2.out.p2b.n_bars == 22 && S2.out.p2b.n_flashes == 5*44 && abs(sum([sb.rows.duration_s]) - (4 + 5*(25 + 14))) < 1e-6, ...
    sprintf('stage 2: 22 bars, 5 repeats (2 beyond the table), one row per repeat and class: %d flashes, %d rows, %.0f s', S2.out.p2b.n_flashes, sb.rows_total, sum([sb.rows.duration_s])));
fn2 = dir(fullfile(exp2, 'p2b', 'Functions', '*.mat'));
check(numel(fn2) == 11 && sum(contains({fn2.name}, 'flashes_80ms')) == 5 && sum(contains({fn2.name}, 'flashes_14ms')) == 5, 'stage 2 function names carry flashes_80ms / flashes_14ms for the read-out''s trial classifier');
dp = dir(fullfile(exp2, 'p2b', 'Patterns', '0001_*.mat'));
check(isscalar(dp) && contains(dp.name, 'bar_flashes_slow') && contains(dp.name, 'FLASHES'), 'stage 2 uses the stage-1 package''s first FLASHES pattern as pattern 1, name keeps FLASHES');
m = load(fullfile(exp2, 'p2b', 'Functions', dir(fullfile(exp2, 'p2b', 'Functions', '0002_*')).name)); f = m.pfnparam.func;
Sq = readtable(fullfile(readout_dir, 'JY1008_stage2_sequence.csv'), 'TextType', 'string', 'Delimiter', ',');
first = Sq(Sq.repeat == 1 & Sq.cls == "flash80" & Sq.order == 1, :);
check(numel(f) == 25*500 && all(f(1:1500) == 1) && f(1501) == first.bar_pattern_frame_1based + 1 && f(1540) == first.bar_pattern_frame_1based + 1 && f(1541) == 1, ...
    'stage 2 PFN rep 1 / 80 ms: 3 s gray, then 80 ms of the first table bar (pattern frame bar + 1) + 920 ms gray (25 s)');
E2 = readtable(fullfile(exp2, 'p2b', 'Reports', 'event_ledger.csv'), 'Delimiter', ',');
check(height(E2) == 220 && sum(E2.flash_ms == 80) == 110 && sum(E2.flash_ms == 14) == 110, 'stage 2 event ledger: 220 flashes, half 80 ms, half 14 ms');
check(isequal(sort(unique(E2.pattern_frame(E2.repeat == 4))), sort(unique(E2.pattern_frame(E2.repeat == 1)))), 'extra repeats reuse the same 22 frames');
dc2 = d2(strcmp(dn2, 'center')); dc2 = dc2(end);
check(~dc2.fallback && isequal(S2.center_shift_px, [0 0]), 'two-stage: center accepted, no shift');

%% 3. No usable PD after stage 1: all 88 bars as today, sites from the Protocol 1 peak
rd3 = fullfile(scratch, 'readout_nopd'); copyfile(readout_dir, rd3);
J = jsondecode(fileread(fullfile(rd3, 'JY1008_stage1.json'))); J.placement.vector_length_28 = 0.02;
if isfield(J, 'sequencer_inputs'), J.sequencer_inputs.usable_pd = false; end
fid = fopen(fullfile(rd3, 'JY1008_stage1.json'), 'w'); fprintf(fid, '%s', jsonencode(J, 'PrettyPrint', true)); fclose(fid);
exp3 = fullfile(scratch, 'cell_C_nopd');
S3 = run_session(exp3, 'dry_run', true, 'cell', 'JY1008', 'side', 'L', 'p1_package', p1_package, 'peak_frame', peak_frame, ...
    'p2_folder', p2pkg_C, 'readout_dir', rd3, 'steps', {'p1', 'p1_peak', 'p2a', 'readout1', 'p2b', 'readout', 'build'}, 'analysis_repo', analysis_repo);
check(strcmp(S3.out.readout1.stage2_mode, 'all88') && S3.decisions(strcmp({S3.decisions.decision}, 'usable_pd')).fallback, 'no usable PD (L28 0.02): flagged, stage 2 = all 88 bars');
sb3 = jsondecode(fileread(fullfile(exp3, 'p2b', 'Reports', 'run_status.json')));
check(sb3.rows_total == 6 && isequal([sb3.rows.pattern_id], [4 5 4 5 4 5]) && isequal([sb3.rows.pfn_id], [3 4 3 4 3 4]) && abs(sum([sb3.rows.duration_s]) - 3*(22 + 11)) < 1e-6, ...
    'all-88 fallback: the package''s two FLASHES rows x 3 reps, the same patterns every rep as run_protocol2 (no Rep1/2/3 functions in this package)');
dc3 = S3.decisions(strcmp({S3.decisions.decision}, 'center'));
check(dc3.fallback && strcmp(dc3.flags, 'no_pd_fallback') && isequal(S3.center_shift_px, round(p1xy - center)), sprintf('center falls back to the Protocol 1 peak: shift %s', mat2str(S3.center_shift_px)));
cfg3 = jsondecode(fileread(fullfile(exp3, 'p3b', 'Reports', 'config.json')));
check(isequal(cfg3.center_shift_px(:).', round(p1xy - center)) && contains(cfg3.center_source, 'Protocol 1 peak'), 'shift and center source recorded in the Prot3b config.json');

%% 4. Center sanity check fails (Protocol 1 peak far from the read-out center): fallback to the peak
exp4 = fullfile(scratch, 'cell_D_far_peak');
S4 = run_session(exp4, 'dry_run', true, 'cell', 'JY1008', 'side', 'L', 'p2_mode', 'full', 'p1_package', p1_package, 'peak_frame', 2, ...
    'readout_dir', readout_dir, 'steps', {'p1', 'p1_peak', 'readout', 'build'}, 'analysis_repo', analysis_repo);
dc4 = S4.decisions(strcmp({S4.decisions.decision}, 'center'));
check(dc4.fallback && contains(dc4.flags, 'near_p1') && ~S4.out.readout.checks.near_p1 && isequal(S4.center_shift_px, round(S4.out.p1_peak.xy - center)), ...
    sprintf('far peak (%.1f px): check near_p1 fails, center falls back to the Protocol 1 peak, shift %s', S4.out.readout.checks.dist_to_p1_px, mat2str(S4.center_shift_px)));
check(~isempty(S4.out.build.p3b.warnings), 'squares that leave the screen after the shift are reported');

%% 5. Override: 'center','p1_peak' (never prompted for), logged
exp5 = fullfile(scratch, 'cell_E_override');
S5 = run_session(exp5, 'dry_run', true, 'cell', 'JY1008', 'side', 'L', 'p2_mode', 'full', 'p1_package', p1_package, 'peak_frame', peak_frame, ...
    'readout_dir', readout_dir, 'center', 'p1_peak', 'steps', {'p1', 'p1_peak', 'readout', 'build'}, 'analysis_repo', analysis_repo);
dc5 = S5.decisions(strcmp({S5.decisions.decision}, 'center'));
check(strcmp(dc5.flags, 'override') && ~dc5.fallback && isequal(S5.center_shift_px, round(p1xy - center)), sprintf('override to the Protocol 1 peak logged, shift %s', mat2str(S5.center_shift_px)));

%% 6. Controller failure during Prot3b and resume
exp6 = fullfile(scratch, 'cell_F_resume');
failing = @() SessionMockController(struct('fail_method', 'startDisplay', 'fail_on_call', 10, 'fail_mode', 'false'));
try
    run_session(exp6, 'dry_run', true, 'cell', 'JY1008', 'side', 'L', 'p2_mode', 'full', 'p1_package', p1_package, 'peak_frame', peak_frame, ...
        'readout_dir', readout_dir, 'steps', {'p1', 'p1_peak', 'readout', 'build', 'p3b', 'p4'}, 'controller_factory', failing, 'analysis_repo', analysis_repo);
    check(false, 'injected failure should have thrown');
catch err
    check(strcmp(err.identifier, 'run_session:controller'), sprintf('injected failure surfaced as %s', err.identifier));
end
S6 = jsondecode(fileread(fullfile(exp6, 'session_state.json'))); st6 = containers.Map({S6.steps.id}, {S6.steps.status});
rs = jsondecode(fileread(fullfile(exp6, 'p3b', 'Reports', 'run_status.json')));
check(strcmp(st6('p3b'), 'failed') && strcmp(st6('p4'), 'pending') && strcmp(rs.state, 'failed') && rs.rows_completed == 9, 'after the failure: p3b failed after 9 rows, p4 pending');
S6 = run_session(exp6, 'dry_run', true, 'readout_dir', readout_dir, 'steps', {'p1', 'p1_peak', 'readout', 'build', 'p3b', 'p4'}, 'analysis_repo', analysis_repo);
st6 = containers.Map({S6.steps.id}, {S6.steps.status});
check(strcmp(st6('p3b'), 'done') && strcmp(st6('p4'), 'done') && any(strcmp({S6.decisions.decision}, 'resume')), 'resume: p3b re-run automatically (logged as a decision), p4 done');

%% 7. Abandon
S7 = run_session(exp4, 'abandon', true);
st7 = containers.Map({S7.steps.id}, {S7.steps.status});
check(strcmp(st7('build'), 'done') && strcmp(st7('p3b'), 'skipped') && ~isempty(S7.finished), 'abandon: done steps kept, the rest skipped, session closed');

%% 8. Duration contract
try
    run_session(fullfile(scratch, 'cell_G'), 'dry_run', true, 'cell', 'JY1008', 'p2_mode', 'full', 'readout_dir', readout_dir, 'steps', {'readout', 'build'}, 'pretrial_s', 2.05, 'analysis_repo', analysis_repo);
    check(false, '2.05 s pretrial should be refused');
catch err
    check(strcmp(err.identifier, 'run_session:duration'), sprintf('2.05 s pretrial refused (%s)', err.identifier));
end

%% 9. End of session: allOff after the last step's cleanup (panels dark), only when an arena step ran
check(isfield(S2.out, 'arena_off') && S2.out.arena_off.ok && isequal({S2.out.arena_off.steps.step}, {'open', 'allOff', 'close'}), 'two-stage session ends with open, allOff, close (panels dark)');
mocks = containers.Map('KeyType', 'double', 'ValueType', 'any');
S9 = run_session(fullfile(scratch, 'cell_H_dark'), 'dry_run', true, 'cell', 'JY1008', 'steps', {'dark30'}, 'controller_factory', @() new_mock(mocks, struct()));
c1 = mocks(1).methodsCalled(); c2 = mocks(2).methodsCalled();
check(mocks.Count == 2 && strcmp(c1{end}, 'close') && isequal(c2, {'open', 'allOff', 'close'}) && S9.out.arena_off.ok, 'allOff on a new connection after the step''s cleanup closed');
mocks = containers.Map('KeyType', 'double', 'ValueType', 'any');
run_session(exp5, 'dry_run', true, 'readout_dir', readout_dir, 'steps', {'readout', 'build'}, 'analysis_repo', analysis_repo, 'controller_factory', @() new_mock(mocks, struct()));
check(mocks.Count == 0, 'no arena step in the call (all done): no controller, no allOff');
mocks = containers.Map('KeyType', 'double', 'ValueType', 'any');
S10 = run_session(fullfile(scratch, 'cell_I_off_fails'), 'dry_run', true, 'cell', 'JY1008', 'steps', {'dark30'}, ...
    'controller_factory', @() new_mock(mocks, struct(), struct('fail_method', 'allOff', 'fail_on_call', 1, 'fail_mode', 'false')));
lg = fileread(fullfile(scratch, 'cell_I_off_fails', 'session_log.txt'));
check(~S10.out.arena_off.ok && ~isempty(S10.finished) && contains(lg, 'FLAG arena not turned off'), 'allOff returning false: flagged, session still completes');

fprintf('\n%d check(s) failed. Output in %s\n', NFAIL, scratch);

function m = new_mock(store, o, o_later)
% a SessionMockController kept in STORE (containers.Map, a handle), numbered in creation order;
% O_LATER (optional) replaces O from the second controller on (the end-of-session allOff)
if nargin > 2 && store.Count >= 1, o = o_later; end
m = SessionMockController(o); store(store.Count + 1) = m;
end

function check(cond, msg)
    global NFAIL
    if cond, fprintf('  PASS  %s\n', msg); else, fprintf(2, '  FAIL  %s\n', msg); NFAIL = NFAIL + 1; end
end
